(7679019, 1255943, 65234, '<td valign="top">Nice light.</td>', 'Nice light.', '2020-11-08 10:18:47.000000', NULL, 1),
(7679020, 1255972, 65234, '<td valign="top">Like the curves, the long exposure and the foliage. On my screen the road looks quite blue and the colors look a little oversaturated.</td>', 'Like the curves, the long exposure and the foliage. On my screen the road looks quite blue and the colors look a little oversaturated.', '2020-11-08 10:21:28.000000', NULL, 1),
(7679021, 1255939, 65234, '<td valign="top">Ooh, that light through the clouds! Love it.</td>', 'Ooh, that light through the clouds! Love it.', '2020-11-08 10:22:42.000000', NULL, 1),
(7679022, 1255935, 65234, '<td valign="top">I like the composition and the bokeh of the many flowers.</td>', 'I like the composition and the bokeh of the many flowers.', '2020-11-08 10:24:43.000000', NULL, 1),
(7679023, 1255947, 65234, '<td valign="top">Beautiful scene. I like that I can see swaths of yellow on the distant mountains. Kind of ties the whole scene together.</td>', 'Beautiful scene. I like that I can see swaths of yellow on the distant mountains. Kind of ties the whole scene together.', '2020-11-08 10:25:30.000000', NULL, 1),
(7679024, 1255862, 65234, '<td valign="top">I like the light and the bokeh here. Would like just a smidge more DOF; I feel like the near leaf tip should be in focus.</td>', 'I like the light and the bokeh here. Would like just a smidge more DOF; I feel like the near leaf tip should be in focus.', '2020-11-08 10:26:28.000000', NULL, 1),
(7679025, 1255971, 65234, '<td valign="top">The last, lonely leaf. Love the light and bokeh.</td>', 'The last, lonely leaf. Love the light and bokeh.', '2020-11-08 10:28:56.000000', NULL, 1),
(7679026, 1255968, 65234, '<td valign="top">I like the composition and the red of the leaf. To my eye it''s just a tad out of focus, though.</td>', 'I like the composition and the red of the leaf. To my eye it''s just a tad out of focus, though.', '2020-11-08 10:30:14.000000', NULL, 1),
(7679029, 1255975, 65234, '<td valign="top">Seems unkind to shear them just as the weather turns colder. I like the old-fashioned sort of feel to this.</td>', 'Seems unkind to shear them just as the weather turns colder. I like the old-fashioned sort of feel to this.', '2020-11-08 10:34:08.000000', NULL, 1),
(7679030, 1255730, 65234, '<td valign="top">Stereotypical autumnal scene with a nice curve to the road for added interest.</td>', 'Stereotypical autumnal scene with a nice curve to the road for added interest.', '2020-11-08 10:35:03.000000', NULL, 1),
(7679031, 1255736, 65234, '<td valign="top">Wow; that background yellow is BRIGHT. But not unrealistically so. Certainly makes a dramatic background for the bird.</td>', 'Wow; that background yellow is BRIGHT. But not unrealistically so. Certainly makes a dramatic background for the bird.', '2020-11-08 10:35:46.000000', NULL, 1),
